const { default: makeWASocket, useMultiFileAuthState, downloadContentFromMessage } = require('@whiskeysockets/baileys');
const fs = require('fs');
const path = require('path');

async function startBot() {
    const { state, saveCreds } = await useMultiFileAuthState('auth');
    const sock = makeWASocket({
        auth: state,
        // CRITICAL: disable auto-read to prevent message being marked as viewed before extraction
        readIncomingMessages: false,
        markOnlineOnConnect: false,
        syncFullHistory: false,
    });

    sock.ev.on('creds.update', saveCreds);

    sock.ev.on('messages.upsert', async ({ messages }) => {
        for (const msg of messages) {
            if (!msg.message) continue;

            // Check for view-once wrapper
            const viewOnce = msg.message.viewOnceMessageV2 || msg.message.viewOnceMessage;
            if (viewOnce) {
                const inner = viewOnce.message; // actual content (image, video, etc.)
                if (!inner) {
                    console.log('Empty stub — message already viewed or stripped.');
                    continue;
                }

                const type = Object.keys(inner)[0]; // 'imageMessage', 'videoMessage', etc.
                const mediaMessage = inner[type];

                // Download media before sending read receipt
                const stream = await downloadContentFromMessage(mediaMessage, type.replace('Message', ''));
                const buffer = await streamToBuffer(stream);

                const ext = type.includes('image') ? 'jpg' : type.includes('video') ? 'mp4' : 'bin';
                const filename = path.join('saved_media', `${msg.key.id}.${ext}`);
                fs.writeFileSync(filename, buffer);
                console.log(`[+] Saved view-once media to ${filename}`);

                // Now mark as read (optional, or leave unread to avoid deletion on sender's side)
                await sock.readMessages([msg.key]);
            }
        }
    });
}

async function streamToBuffer(stream) {
    const chunks = [];
    for await (const chunk of stream) chunks.push(chunk);
    return Buffer.concat(chunks);
